  Phase("commission and prerequisites");Need(!(bool)Call(Journal(),"CanAccept",Q("room-to-work"))&&!(bool)Call(Journal(),"CanAccept",Q("road-survey")),"Quest order locked");await Accept("timber-commission");Move((Vector3)Get(Foreman(),"ApproachPosition"));await Talk();await Turn("timber-commission");await Accept("room-to-work");
  Phase("interruptible forestry work");var sites=Sites("room-to-work");Move((Vector3)Get(sites[4],"ApproachPosition"));await Begin(sites[4]);Call(Input(),"Cancel");await Until(()=>Get(sites[4],"Worker")==null,"Cancellation");Need((int)Get(State("room-to-work"),"count")==0,"Cancelled work has no credit");await Begin(sites[4]);Need((bool)Call(Get(player,"Motor"),"MoveTo",player.transform.position+Vector3.right*2),"Moving cancels");await Until(()=>Get(sites[4],"Worker")==null,"Move cancellation");Call(Get(player,"Motor"),"Stop");Move((Vector3)Get(sites[4],"ApproachPosition"));await Begin(sites[4]);Set(Get(player,"Health"),"Invulnerable",false);var packet=Activator.CreateInstance(T("DiceFree.Combat.DamageResult"));Set(packet,"mitigated",1f);Call(Get(player,"Health"),"ApplyPacket",null,packet);Set(Get(player,"Health"),"Invulnerable",true);await Until(()=>Get(sites[4],"Worker")==null,"Damage interruption");Need((int)Get(State("room-to-work"),"count")==0,"Interruptions cannot advance work");
